const field = ctx.newField();
const greenEdgeX = -768;
const ashEdgeX = 768;
for (let y = 0; y < ctx.size; y++) {
  for (let x = 0; x < ctx.size; x++) {
    const eastwardness = (ctx.originX + x - greenEdgeX) / (ashEdgeX - greenEdgeX);
    field[y * ctx.size + x] = Math.max(0, Math.min(1, eastwardness));
  }
}
return field;

const field = ctx.newField();
const lotSpan = 192;
for (let y = 0; y < ctx.size; y++) {
  for (let x = 0; x < ctx.size; x++) {
    const lotX = Math.floor((ctx.originX + x) / lotSpan);
    const lotY = Math.floor((ctx.originY + y) / lotSpan);
    const warded = ctx.hash01(lotX, lotY, 'ward lot') < 0.28;
    field[y * ctx.size + x] = warded ? 1 : 0;
  }
}
return field;

const maze = ctx.tilesInput('a');
const char = ctx.fieldInput('b');
const tiles = ctx.newTiles();
if (!maze || !char) return tiles;
const hedgeWall = 24;
const wardPath = 8;
const scorchedWall = 23;
const ashGround = 22;
for (let y = 0; y < ctx.size; y++) {
  for (let x = 0; x < ctx.size; x++) {
    const i = y * ctx.size + x;
    tiles[i] = -1;
    if (char[i] < 0.62) continue;
    const ruin = ctx.hash01(ctx.originX + x, ctx.originY + y, 'scorch');
    if (maze[i] === hedgeWall) tiles[i] = ruin < 0.3 ? ashGround : scorchedWall;
    if (maze[i] === wardPath) tiles[i] = ashGround;
  }
}
return tiles;
